<?php $manage = can('customers.manage'); ?>
<div class="top"><div><h2 style="margin:0"><?= e($c['name']) ?></h2><span class="muted">Customer since <?= e(fmt_date($c['created_at'])) ?></span></div><div><?php if (can('requests.create')): ?><a class="btn alt" href="/staff/requests/new?customer=<?= (int) $c['id'] ?>">+ Order</a> <?php endif; ?><?php if ($invoices !== null): ?><a class="btn" href="/staff/invoices/new?customer=<?= (int) $c['id'] ?>">+ Invoice</a><?php endif; ?></div></div>
<div class="grid g2" style="align-items:start">
<div class="card"><h3>Details</h3>
<?php if ($manage): $old = $c; if (str_ends_with($old['email'], '@walkin.invalid')) { $old['email'] = ''; } ?>
<form method="post" action="/staff/customers/<?= (int) $c['id'] ?>"><?= csrf_field() ?><?php require __DIR__ . '/customer_fields.php'; ?><button class="btn">Save</button></form>
<?php else: ?><dl class="kv"><dt>Email</dt><dd><?= e($c['email']) ?></dd><dt>Phone</dt><dd><?= e((string) $c['phone']) ?></dd><dt>Address</dt><dd><?= nl2br(e((string) $c['address'])) ?></dd><dt>GSTIN</dt><dd><?= e((string) $c['gstin']) ?></dd><dt>State</dt><dd><?= e((string) $c['state']) ?></dd></dl><?php endif; ?></div>
<div><div class="card mb"><h3>Orders</h3><div class="tw"><table><?php foreach ($orders as $o): ?><tr><td><a href="/staff/requests/<?= (int) $o['id'] ?>"><?= e($o['ref']) ?></a></td><td><?= e($o['material']) ?> ×<?= (int) $o['quantity'] ?></td><td><?= status_badge($o['status']) ?></td><td class="right"><?= e(money($o['quote_amount'])) ?></td></tr><?php endforeach; if (!$orders): ?><tr><td class="muted">No orders yet.</td></tr><?php endif; ?></table></div></div>
<?php if ($invoices !== null): ?><div class="card"><h3>Invoices</h3><div class="tw"><table><?php foreach ($invoices as $i): ?><tr><td><a href="/staff/invoices/<?= (int) $i['id'] ?>"><?= e($i['number']) ?></a></td><td><?= e(fmt_date($i['issue_date'])) ?></td><td class="right"><?= e(money($i['total'])) ?></td><td><?= badge(INVOICE_STATUSES[$i['status']], ['paid' => 'p-ok', 'void' => 'p-bad', 'issued' => 'p-warn'][$i['status']]) ?></td></tr><?php endforeach; if (!$invoices): ?><tr><td class="muted">No invoices yet.</td></tr><?php endif; ?></table></div></div><?php endif; ?></div>
</div>
